package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class NicknameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property nickname of user profile ")
  void test_nickname_v_o_builder() {
    Assertions.assertFalse(NicknameVO.nullValue().getNickname().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(NicknameVO.tryFrom(null).getNickname().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", NicknameVO.from("one").getNickname().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> NicknameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", NicknameVO.from("one").toString());
  }
}
